-- nsrit-discovery-queries.sql
-- Legacy dev DB copy `lms_click` (MySQL 8.0, local port 3310). SELECT-only. No secrets, no PII selected.
-- NSRIT identity: college.id=6 (name NSRIT, unique_id nsrit42, org_id=6), organization.id=6 (name NSRIT).

-- 1. Identity of NSRIT
select id,name,org_id,unique_id,is_deleted,created_at from college;
select id,name,is_deleted from organization;
select college_id,host,is_primary,is_verified from tenant_domain where college_id=6;
select scope_type,scope_id,setting_key from app_setting where scope_id=6;

-- 2. Name variants (nsrit / n s raju) across name-bearing tables
select 'new_program',id,name from new_program where name regexp 'nsr|raju';
select 'course',id,course_name from course where course_name regexp 'nsr|raju';

-- 3. Hierarchy: department -> new_program -> batch/class/semester (batch.program_id and learner.program_id point at new_program, NOT program)
select d.college_id, count(*) from department d group by 1;
select 'learner class/program college', d.college_id, count(*) from learner l left join class c on c.id=l.class_id left join new_program p on p.id=c.program_id left join department d on d.id=p.dept_id where l.college_id=6 group by 2;

-- 4. Enum/status value sets
select attendance_status,count(*) from attend group by 1;
select grading_status,graded,is_grade_published,count(*) from student_assignment group by 1,2,3;
select application_status,count(*) from job_application group by 1;
select status,kind,count(*) from job_offer group by 1,2;
select lifecycle_status,count(*) from job group by 1;
select faculty_type,count(*) from faculty where college_id=6 or organization_id=6 group by 1;   -- ordinal of FacultyType enum
select recipient_type, event, channel, status, count(*) from notification_outbox group by 1,2,3,4;   -- PENDING rows must not be loaded

-- 5. Timezone evidence (hour histograms): schedule/deadline columns are naive IST wall-clock; created_at-style columns are naive UTC
select hour(start_time),count(*) from class_schedule group by 1 order by 1;
select hour(due_at),count(*) from quizzes group by 1;
select hour(created_at),count(*) from notification group by 1;

-- 6. Programmable objects present in the legacy schema (result: none)
select trigger_name from information_schema.triggers where trigger_schema='lms_click';
select table_name from information_schema.views where table_schema='lms_click';
select routine_name from information_schema.routines where routine_schema='lms_click';
select event_name from information_schema.events where event_schema='lms_click';

