-- 8. Identity collapse analysis (counts only). Phone normalised to last 10 digits, email lower(trim()).
create temporary table idn as
select 'LEARNER' t, id, right(regexp_replace(coalesce(contact_mobile,''),'[^0-9]',''),10) ph, lower(trim(contact_mail)) em, college_id c, concat_ws(' ',first_name,last_name) nm, roll_number rn from learner
union all select 'FACULTY', id, right(regexp_replace(coalesce(contact_mobile,''),'[^0-9]',''),10), lower(trim(contact_mail)), coalesce(college_id,organization_id), concat_ws(' ',first_name,last_name), null from faculty
union all select 'RECRUITER', id, right(regexp_replace(coalesce(contact_mobile,''),'[^0-9]',''),10), lower(trim(contact_mail)), null, concat_ws(' ',first_name,last_name), null from recruiter;
create temporary table idn2 as select * from idn;
select t, count(*) from idn where c=6 group by t;
select count(*) from (select ph from idn where c=6 group by ph having count(*)>1) x;            -- NSRIT shared phones
select count(distinct a.ph) from idn a join idn2 b on b.ph=a.ph and not (b.t=a.t and b.id=a.id) and coalesce(b.c,-1)<>6 where a.c=6;  -- NSRIT phone shared with non-NSRIT account
select count(*) from (select em from idn where c=6 and em<>'' group by em having count(*)>1) x;  -- dup emails
select t,count(*) from idn where c=6 and (em is null or em='') group by t;                         -- no email
select count(*) from learner_acct_verification where learner_id in (select id from learner where college_id=6);
